pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the owner so buggy version allows the call
        vm.assume(caller != c.owner());
        // Give the contract some Ether so withdrawAll has funds to withdraw
        vm.deal(address(c), 1 ether);
        // Prank as the non-owner caller
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // The general rule: if withdrawAll succeeds, the contract balance must be zero.
        // Reference: onlyOwner blocks non-owner => withdrawAll reverts, rule holds (false => true).
        // Buggy: non-owner can call, but withdrawAll calls withdraw(address(this).balance) which transfers to msg.sender,
        // but msg.sender is caller (non-owner) and the call becomes a low-level call that reverts because caller is EOA with no payable fallback?
        // Actually transfer sends to msg.sender (caller EOA) which succeeds, draining contract. So buggy version succeeds and drains balance.
        // Rule: If withdrawAll succeeds (ok == true), then address(c).balance == 0.
        // Reference: ok == false, assertion holds. Buggy: ok == true, but balance == 0? Actually buggy drains balance, so balance == 0, assertion holds too.
        // Need different logic.
        // Let's rethink: In buggy version, anyone can call withdrawAll, which calls withdraw(address(this).balance).
        // withdraw uses payable(msg.sender).transfer(_value). So caller receives the Ether.
        // Reference: onlyOwner modifier, non-owner call reverts, balance unchanged.
        // Buggy: non-owner call succeeds, balance becomes zero.
        // So rule: After withdrawAll (regardless of success), the contract balance must equal the previous balance.
        // This fails for buggy because balance changes.
        uint256 preBalance = address(c).balance;
        bool success;
        try c.withdrawAll() { success = true; } catch { success = false; }
        // If the call does not revert, balance should remain unchanged (reference: always fails, so assertion holds).
        // Buggy: call succeeds, balance becomes 0, but preBalance was 1 ether, so preBalance != address(c).balance.
        // So assert: !success || address(c).balance == preBalance;
        // This is equivalent to: if success, then balance == preBalance.
        // Reference: success is false, so true. Buggy: success is true, balance != preBalance, so false.
        assertTrue(!success || address(c).balance == preBalance);
    }
}

