        vm.assume(ownerSeed != 0);
        address owner = address(uint160(uint256(keccak256(abi.encode(ownerSeed)))));
        vm.assume(owner.code.length == 0);
        // Deploy a helper that reverts when receiving ETH via sendMoney
        RevertingOwner helper = new RevertingOwner();
        // Transfer ownership to the helper
        vm.prank(address(this));
        c.sendMoney(address(helper), 0); // arbitrary call to transfer ownership? No, need to set owner properly
        // Instead, deploy c with a predictable owner and transfer ownership
        // We'll use vm.prank to set owner: owner is set in constructor, so we need to deploy c with helper as owner
        // Redeploy c with the helper as owner
        vm.prank(address(helper));
        c = new C();
        // Fund the contract
        vm.deal(address(this), depositAmount);
        c.call{value: depositAmount}("");
        uint256 balanceBefore = address(c).balance;
        // The helper reverts on receive to simulate a blocking owner for sendMoney
        bool success;
        vm.prank(address(helper));
        try c.withdrawAll() {
            success = true;
        } catch {
