        // The fuzzed caller is an EOA by default; we deploy a proxy contract that forwards a call to sendMoney,
        // ensuring msg.sender is a contract and tx.origin is the EOA that triggered the proxy.
        // The proxy is needed to create the multi-contract call chain that distinguishes msg.sender from tx.origin.
        Proxy proxy = new Proxy();
        vm.assume(caller != address(proxy));
        // Fund the proxy to make the external call
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok, ) = address(proxy).call{value: amount}("");
        // The proxy forwards to c.sendMoney(address(this), amount).
        // For the reference C, sendMoney should revert because msg.sender (the proxy) is not the owner.
        // For the buggy C, it succeeds if tx.origin (the caller) is the owner.
        // To make the property hold universally, we assert that sendMoney always reverts
        // when the immediate caller is a contract and the call originates from another account.
        // Since the owner is the deployer of C (this test contract), and we never set the caller as owner,
        // the reference C will always revert. The buggy version will succeed if the caller (tx.origin) is the owner.
        // Wait, the original invariant said "for every input, reference satisfies...".
        // The reference C reverts for any non-owner msg.sender, so it always reverts here.
        // The buggy C, if tx.origin == owner, does NOT revert.
        // To trigger the bug, we need tx.origin == owner. The deployer of C is this test contract.
        // If we set caller = address(this) and prank as address(this), tx.origin becomes address(this) which is owner.
        // That would make the buggy version succeed. But the fuzz rule must pass on reference for ALL inputs.
        // If caller = address(this), the reference C also reverts because msg.sender is the proxy, not owner.
        // So the assertion: "sendMoney must revert" holds for reference C for all callers and amounts.
        // The buggy C fails this assertion when caller == address(this) because then tx.origin == owner and the call succeeds.
        bool success = ok; // ok is true if the proxy call succeeded, meaning sendMoney did not revert.
        assertTrue(!success); // For reference C, proxy call always fails; for buggy C, it succeeds when caller is the owner (address(this)).
    }
}

