pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address intermediate, uint256 value, bool asOwner) public {
        // restrict intermediate to exclude the owner itself to ensure a proper chain
        vm.assume(intermediate != c.owner());
        vm.assume(intermediate != address(0));
        bound(value, 0, address(this).balance);

        // deploy an adversarial contract that is used by the true owner
        IntermediateCaller attacker = new IntermediateCaller(c);
        vm.assume(address(attacker) != c.owner());

        // fund owner for gas, give the attacker some ETH to forward if needed
        vm.deal(c.owner(), 10 ether);
        vm.deal(address(attacker), value);

        address caller = asOwner ? c.owner() : intermediate;
        bool ok = false;

        if (asOwner && caller != address(attacker)) {
            // The owner calls attacker.forwardSendMoney which calls c.sendMoney
            // This creates a call chain where tx.origin == owner, msg.sender != owner
            vm.prank(c.owner());
            try attacker.forwardSendMoney(value) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // A random caller (non-owner) tries directly
            address target = address(0x1234);
            vm.prank(caller);
            try c.sendMoney(target, value) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // GENERAL RULE: if msg.sender != owner, the call MUST revert.
        // In the asOwner case with a contract intermediate, reference reverts (msg.sender is attacker),
        // buggy continues (tx.origin == owner). For non-owner direct calls, both revert => ok is false.
        assertTrue(
            asOwner ? !ok : !ok
        );
    }
}

contract IntermediateCaller {
    C public c;
    constructor(C _c) { c = _c; }
    function forwardSendMoney(uint256 value) external payable {
        c.sendMoney{value: value}(address(0xbeef));
    }
}
